【図解】共有物に関する行為の整理
　保存行為＝各共有者が単独で可（修繕・不法占拠者への明渡請求★）
　管理行為＝持分「価格」の過半数（人数ではない★）。短期の賃借権設定（土地5年・建物3年以内）や軽微な変更も過半数
　変更行為（軽微を除く）・売却＝全員の同意
　→共有物を独占使用する共有者にも、当然には明渡しを請求できない（持分に応じた使用権があるため）

・自分の持分の処分（売却・抵当権設定）は単独で自由★
・共有物の管理者の選任・解任＝持分価格の過半数
・所在等不明共有者がいるとき：裁判所の決定を得て、残りの共有者だけで変更・管理が可能（改正）
・共有物分割：いつでも請求可。5年以内の不分割特約は有効（更新可）
・協議が調わないとき→裁判所へ（現物分割・賠償分割・競売による代金分割）
・共有者の1人が死亡し相続人がいないとき→その持分は特別縁故者への財産分与の対象となり、それもなければ他の共有者に帰属★

