━━━━━━━━━━━━━━━━━━━━━━
・顕名：「Aの代理人B」と本人のためにすることを示す
　→顕名を欠くと、代理人自身のためにした契約とみなされる（相手方が知り・知り得たときは本人に効果帰属★）
