宅建業法も、条文だけでなく判例・行政の解釈運用（国土交通省の「解釈・運用の考え方」等）が出題の元ネタになります。
このセクションでは、条文の文言だけでは判断しづらい「実務上の解釈」を中心にまとめます。

━━━━━━━━━━━━━━━━━━━━━━
