━━━━━━━━━━━━━━━━━━━━━━
【図解】機構が直接融資できる主な例外
　○災害復興建築物の建設・購入資金★
　○密集市街地の建替え等、災害予防関連
　○子育て世帯・高齢者世帯向けの賃貸住宅の建設・改良資金★
　○マンションの共用部分の改良（リフォーム）資金★
　○高齢者の自宅バリアフリー・耐震改修（死亡時一括償還制度を利用できる★）
　×一般の個人が自宅を新築・購入する資金の直接融資は行わない★

