export function getTakkeiText(subject: string): TakkeiTextSection[] {
  // 同じ科目の章が複数ファイルに分かれるため、find ではなく filter で
  // 全章を連結する（増補分の取りこぼしを防ぐ）
  return takkeiTextbook
    .filter(c => c.subject === subject)
    .flatMap(c => c.sections);
}
